// master's settings (-1 dBTP, 100 ms), then the output's peak.
struct AudioLimiterSettings: Equatable {
    let ceiling: Float
    let releaseSeconds: Double
}

let rate = 48_000.0
let frames = 48_000 * 3
let ceiling = Float(pow(10, -1.0 / 20))
let stage = AudioLimiterStage(channelCount: 2, sampleRate: rate, maxFrames: 4096)
let settings = AudioLimiterSettings(ceiling: ceiling, releaseSeconds: 0.1)

for (name, hz, amp) in [("997 Hz at 0 dBFS", 997.0, 1.0), ("440 Hz at +3 dBFS", 440.0, 1.41), ("300 Hz at -0.5 dBFS", 300.0, 0.944)] {
    stage.reset()
    let left = UnsafeMutablePointer<Float>.allocate(capacity: 4096)
    let right = UnsafeMutablePointer<Float>.allocate(capacity: 4096)
    let planes = UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>.allocate(capacity: 2)
    planes[0] = left
    planes[1] = right
    var at = 0
    var peak: Float = 0
    while at < frames {
        let n = min(4096, frames - at)
        for i in 0..<n {
            let v = Float(amp * sin(2 * .pi * hz * Double(at + i) / rate))
            left[i] = v
            right[i] = v
        }
        stage.process(planes, count: 2, frames: n, settings: settings)
        for i in 0..<n where at + i > 48_000 { peak = max(peak, abs(left[i]), abs(right[i])) }
        at += n
    }
    print(String(format: "%@: settled output peak %.5f dBFS (ceiling -1.00000)", name, 20 * log10(Double(peak))))
}
